use vstd::prelude::*;

verus! {

fn amax(a: Vec<i8>) -> (result: i8)
    requires
        // The array must be non‐empty.
        a.len() > 0,
    ensures
        // (1) result is at least as large as every element of a
        forall j: nat :: j < (a.len() as nat) ==> a[j as usize] <= result,
    ensures
        // (2) there is a first position idx0 where a[idx0] == result
        exists idx0: nat ::
            idx0 < (a.len() as nat) &&
            a[idx0 as usize] == result &&
            // and all earlier entries are strictly smaller
            forall j: nat :: j < idx0 ==> a[j as usize] < result,
{
    // We'll work in Viper's nat domain up to the length of the vector
    let n: nat = a.len() as nat;

    // i will scan from 1..n,  max_i tracks the first‐occurrence index
    let mut i:   nat = 1;
    let mut max_i: nat = 0;

    // Loop invariant describing that in the prefix [0..i)
    //   • max_i < i
    //   • for all j < i, a[j] ≤ a[max_i]
    //   • for all k < max_i, a[k] < a[max_i]
    // thus max_i is the first‐occurrence of the maximum in [0..i).
    while i < n
        invariant
            i <= n,
            max_i < i,
            forall j: nat :: j < i ==> a[j as usize] <= a[max_i as usize],
            forall k: nat :: k < max_i ==> a[k as usize] < a[max_i as usize],
        decreases
            n - i,
    {
        if a[i as usize] > a[max_i as usize] {
            // found a strictly larger element at i, so it becomes the new max
            max_i = i;
        } else {
            // else branch reuses the negation of the test to re‐establish
            //   a[i] ≤ a[max_i]
            assert(a[i as usize] <= a[max_i as usize]);
        }
        // advance the scan
        i = i + 1;
    }

    // at exit i == n, and the invariants give
    //   ∀ j < n: a[j] ≤ a[max_i],     and      ∀ k < max_i: a[k] < a[max_i]
    // so setting result := a[max_i] meets both post‐conditions.
    let res = a[max_i as usize];
    result = res;
}

} // end verus!

